<template>
  <div class="page-container gpm-page">
    <div class="page-head"><div><h2>种植主体管理</h2><p>统一维护青贮饲料种植主体基础档案。</p></div><el-button type="primary" @click="openEdit()">新增主体</el-button></div>
    <div class="panel">
      <div class="panel-title"><span class="title-text">种植主体</span><span class="title-extra">共 {{ rows.length }} 个</span></div>
      <el-form :inline="true" class="filters"><el-form-item label="关键字"><el-input v-model="filters.keyword" clearable placeholder="名称/负责人/编号" @keyup.enter="load" /></el-form-item><el-form-item label="类型"><el-select v-model="filters.type" clearable placeholder="全部" style="width:140px"><el-option label="合作社" value="cooperative"/><el-option label="家庭农场" value="family_farm"/><el-option label="农业企业" value="enterprise"/><el-option label="种植大户" value="big_household"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" clearable placeholder="全部" style="width:110px"><el-option label="启用" value="启用"/><el-option label="停用" value="停用"/></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button></el-form>
      <el-table :data="rows" stripe height="calc(100vh - 270px)"><el-table-column prop="id" label="主体编号" width="120"/><el-table-column prop="name" label="主体名称" min-width="220" show-overflow-tooltip/><el-table-column prop="type" label="主体类型" width="110"><template #default="{row}">{{ typeName(row.type) }}</template></el-table-column><el-table-column prop="owner" label="负责人" width="100"/><el-table-column prop="phone" label="联系手机" width="130"/><el-table-column prop="primaryCrop" label="主要作物" width="100"/><el-table-column prop="regionName" label="所属行政区划" min-width="180" show-overflow-tooltip/><el-table-column prop="area" label="种植规模(亩)" width="120"/><el-table-column label="启用状态" width="85"><template #default="{row}"><el-tag size="small" :type="row.status === '启用' ? 'success' : 'info'">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="关联地块" width="90"><template #default="{row}"><el-button link type="primary">{{ row.plotCount || 0 }}</el-button></template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button></template></el-table-column></el-table><el-empty v-if="!rows.length" description="暂无种植主体" />
    </div>
    <el-dialog v-model="visible" :title="form.id ? '编辑种植主体' : '新增种植主体'" width="680px"><el-form :model="form" label-width="100px"><el-row :gutter="16"><el-col :span="12"><el-form-item label="主体名称" required><el-input v-model="form.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="主体类型" required><el-select v-model="form.type" style="width:100%"><el-option label="合作社" value="cooperative"/><el-option label="家庭农场" value="family_farm"/><el-option label="农业企业" value="enterprise"/><el-option label="种植大户" value="big_household"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="负责人" required><el-input v-model="form.owner"/></el-form-item></el-col><el-col :span="12"><el-form-item label="联系手机" required><el-input v-model="form.phone" maxlength="11"/></el-form-item></el-col><el-col :span="12"><el-form-item label="主要作物" required><el-select v-model="form.primaryCrop" style="width:100%"><el-option label="青贮玉米" value="青贮玉米"/><el-option label="苜蓿" value="苜蓿"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="所属行政区划" required><el-input v-model="form.regionName" placeholder="请输入所属行政区划"/></el-form-item></el-col><el-col :span="12"><el-form-item label="种植规模"><el-input-number v-model="form.area" :min="0" :precision="1" style="width:100%"/><span class="unit-tip">亩</span></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { fetchSilGrowers, saveSilGrower } from '@/api/sil'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const rows = ref([]); const visible = ref(false); const filters = reactive({ keyword: '', type: '', status: '' }); const emptyForm = () => ({ id: '', name: '', type: 'cooperative', owner: '', phone: '', primaryCrop: '青贮玉米', regionName: userStore.regionName || '', area: 0, muInvestment: 0, muNetIncome: 0, status: '启用' }); const form = reactive(emptyForm()); const typeName = (type) => ({ cooperative: '合作社', family_farm: '家庭农场', enterprise: '农业企业', big_household: '种植大户' }[type] || type); const load = async () => { rows.value = (await fetchSilGrowers(userStore.role, filters)).map((row) => ({ ...row, type: row.type || 'big_household', regionName: row.regionName || row.regionCode || '—' })) }; const openEdit = (row) => { Object.assign(form, emptyForm(), row || {}); visible.value = true }; const save = async () => { if (!form.name || !form.owner || !form.phone || !form.regionName || !form.primaryCrop) return ElMessage.warning('请完整填写主体基础信息'); const result = await saveSilGrower({ ...form, area: Number(form.area || 0) }, userStore.role); if (!result.success) return ElMessage.error(result.message || '保存失败'); ElMessage.success('主体档案已保存'); visible.value = false; load() }; onMounted(load)
</script>
<style scoped lang="scss">.gpm-page{gap:12px;overflow:auto}.page-head{display:flex;justify-content:space-between;align-items:flex-start}.page-head h2{margin:4px 0;color:var(--ah-text);font-size:22px}.page-head p{color:var(--ah-text-secondary);font-size:13px}.filters{display:flex;align-items:center;flex-wrap:wrap}.filters :deep(.el-form-item){margin-bottom:12px;margin-right:12px}.unit-tip{margin-left:8px;color:var(--ah-text-secondary);font-size:12px}</style>
